#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int main() {
    int n, target;
    if (cin >> n >> target) {
        vector<int> nums(n);
        for (int i = 0; i < n; i++) cin >> nums[i];
        unordered_map<int, int> mp;
        for (int i = 0; i < n; i++) {
            int diff = target - nums[i];
            if (mp.count(diff)) {
                cout << mp[diff] << " " << i << endl;
                return 0;
            }
            mp[nums[i]] = i;
        }
    }
    return 0;
}

